class Translator:

    def __init__(self, lang: str=DEFAULT_LANGUAGE):
        self.lang = lang if lang in SUPPORTED_LANGUAGES else DEFAULT_LANGUAGE

    def set_language(self, lang: str):
        if lang in SUPPORTED_LANGUAGES:
            self.lang = lang

    def tr(self, key: str, **kwargs) -> str:
        text = STRINGS.get(self.lang, STRINGS[DEFAULT_LANGUAGE]).get(key, STRINGS[DEFAULT_LANGUAGE].get(key, key))
        if kwargs:
            try:
                return text.format(**kwargs)
            except (KeyError, ValueError):
                return text
        return text
